package com.networkzero.session;

import com.networkzero.net.Network;
import com.networkzero.room.GameState;
import java.util.*;
import com.networkzero.puzzles.*;

/** Deterministic authoritative puzzle mutations. UI-only selections never enter this class. */
public final class IntentHandler {
    public record Result(boolean accepted,String notice,String event) { public static Result ok(){return new Result(true,"","");} public static Result reject(String s){return new Result(false,s,"");} }
    private final LockManager locks=new LockManager();
    private static final Set<String> PICKUPS=Set.of("crimper","rj45_box","cable_coil");
    private static final List<String> WIRE_ANSWER=List.of("White-Orange","Orange","White-Green","Blue","White-Blue","Green","White-Brown","Brown");
    private static final String[] BOARD_ANSWER={"Router","Switch","PC1","PC3"};
    private static final int[][] LINKS={{1,5},{2,3},{4,6},{7,8}};
    public Result apply(GameState s,Network.Intent in,String player){if(in==null||in.type==null)return Result.reject("Invalid action.");switch(in.type){
        case PICK_UP->{if(!PICKUPS.contains(in.a)||s.pickedUp.contains(in.a)||s.inventory.size()>=6)return Result.reject("Item is unavailable.");s.pickedUp.add(in.a);s.inventory.add(switch(in.a){case "crimper"->"Crimping Tool";case "rj45_box"->"RJ45 Connectors";default->"Cable Coil";});return Result.ok();}
        case OPEN_PANEL->{if(s.roomNumber==2||s.roomNumber==3){if(!Set.of("cabinet","log_archive","service_register","cctv_wall","terminal2","terminal3","exit_keypad").contains(in.a))return Result.ok();String owner=locks.acquire(s,in.a,player);return owner==null?Result.ok():Result.reject(owner+" is using this.");}if(!Set.of("crimp","patch","topology","terminal","keypad").contains(in.a))return Result.ok();String owner=locks.acquire(s,in.a,player);return owner==null?Result.ok():Result.reject(owner+" is using this.");}
        case CLOSE_PANEL->{locks.release(s,in.a,player);if((s.roomNumber==2||s.roomNumber==3)&&"exit_keypad".equals(in.a))s.doorCode="";return Result.ok();}
        case SWAP_WIRES->{if(!owns(s,"crimp",player))return Result.reject("Open the cable crimp panel first.");if(in.i<0||in.j<0||in.i>=8||in.j>=8)return Result.reject("Invalid wire selection.");String t=s.wires[in.i];s.wires[in.i]=s.wires[in.j];s.wires[in.j]=t;return Result.ok();}
        case SUBMIT_CRIMP->{if(!owns(s,"crimp",player))return Result.reject("Open the cable crimp panel first.");if(!s.inventory.containsAll(List.of("Crimping Tool","RJ45 Connectors","Cable Coil")))return Result.reject("You need the crimping tool, connectors, and cable coil.");if(!Arrays.asList(s.wires).equals(WIRE_ANSWER))return Result.reject("Wire order is incorrect.");s.inventory.removeAll(List.of("Crimping Tool","RJ45 Connectors","Cable Coil"));s.inventory.add("Patch Cable");s.solved.add("P3");return new Result(true,"","CableCrimped");}
        case PATCH_CLICK_PORT->{if(!owns(s,"patch",player))return Result.reject("Open the patch panel first.");if(in.i<1||in.i>8)return Result.reject("Invalid port.");if(in.j>0){if(in.j>8||in.j==in.i||portUsed(s,in.i)||portUsed(s,in.j))return Result.reject("Those ports cannot be connected.");for(int[] link:s.links)if(link[0]==in.i&&link[1]==in.j||link[0]==in.j&&link[1]==in.i)return Result.reject("That link already exists.");s.links.add(new int[]{in.i,in.j});s.portPick=-1;}else if(s.portPick<1)s.portPick=in.i;else{int a=s.portPick,b=in.i;s.portPick=-1;if(a==b||portUsed(s,b))return Result.reject("That port is already linked.");s.links.add(new int[]{a,b});}return Result.ok();}
        case PATCH_REMOVE_LINK->{if(!owns(s,"patch",player))return Result.reject("Open the patch panel first.");for(Iterator<int[]> it=s.links.iterator();it.hasNext();){int[] l=it.next();if((l[0]==in.i&&l[1]==in.j)||(l[0]==in.j&&l[1]==in.i)){it.remove();return Result.ok();}}return Result.reject("Link not found.");}
        case SUBMIT_PATCH->{if(!owns(s,"patch",player))return Result.reject("Open the patch panel first.");if(!s.inventory.contains("Patch Cable"))return Result.reject("You need a patch cable.");if(!sameLinks(s.links,LINKS))return Result.reject("Check the patch panel links.");s.inventory.remove("Patch Cable");s.routerOnline=true;s.solved.add("P4");return new Result(true,"","RouterOnline");}
        case WHITEBOARD_PLACE->{if(!owns(s,"topology",player))return Result.reject("Open the whiteboard first.");if(in.i<0||in.i>=4||!Set.of(BOARD_ANSWER).contains(in.a))return Result.reject("Invalid device placement.");s.board[in.i]=in.a;return Result.ok();}
        case WHITEBOARD_RETURN->{if(!owns(s,"topology",player))return Result.reject("Open the whiteboard first.");if(in.i<0||in.i>=4)return Result.reject("Invalid board slot.");s.board[in.i]="";return Result.ok();}
        case SUBMIT_WHITEBOARD->{if(!owns(s,"topology",player))return Result.reject("Open the whiteboard first.");if(!Arrays.equals(s.board,BOARD_ANSWER))return Result.reject("The topology is not correct.");s.boardSolved=true;s.solved.add("P6");return new Result(true,"","WhiteboardSolved");}
        case TERMINAL_COMMAND->{if(s.roomNumber==2||s.roomNumber==3)return terminal2(s,in.a,player);if(!owns(s,"terminal",player))return Result.reject("Open the terminal first.");String[] p=in.a.trim().split("\\s+",3);if(p.length==3&&p[0].equalsIgnoreCase("set")){switch(p[1].toLowerCase(Locale.ROOT)){case "ip"->s.ip=p[2];case "mask"->s.mask=p[2];case "gateway"->s.gateway=p[2];default->{return Result.reject("Unknown setting.");}}return Result.ok();}if(p.length>=2&&p[0].equalsIgnoreCase("ping")&&s.routerOnline&&s.ip.equals("192.168.1.30")&&s.mask.equals("255.255.255.0")&&s.gateway.equals("192.168.1.1")&&p[1].equals(s.gateway)){s.pcSolved=true;s.solved.add("P7");return new Result(true,"","TerminalSolved");}return Result.ok();}
        case KEYPAD_SUBMIT->{if(s.roomNumber==2||s.roomNumber==3){if(!owns(s,"exit_keypad",player))return Result.reject("Open the exit keypad first.");if(!s.lockdownReleased)return Result.reject("The lock is sealed. The lockdown is still active.");if(!s.doorConfirmHost||!s.doorConfirmClient)return Result.reject("Both operators must confirm first.");if(Room2Config.doorCode().equals(in.a)||Room3Config.doorCode().equals(in.a)){s.room2Complete=true;s.room3Complete=true;s.roomComplete=true;return new Result(true,"","EndingStart");}return Result.reject("Wrong code.");}if(!owns(s,"keypad",player))return Result.reject("Open the exit keypad first.");if(!s.pcSolved)return Result.reject("The door is network-locked.");if("2791".equals(in.a)){s.roomComplete=true;return new Result(true,"","RoomComplete");}return Result.reject("Wrong code.");}
        case DIAL_SET->{if((s.roomNumber!=2&&s.roomNumber!=3)||!owns(s,"cabinet",player))return Result.reject("Open the locked cabinet first.");if(in.i<0||in.i>2||in.j<0||in.j>9)return Result.reject("Invalid dial setting.");s.dialDigits[in.i]=in.j;return Result.ok();}
        case DRAWER_OPEN->{if((s.roomNumber!=2&&s.roomNumber!=3)||!owns(s,"cabinet",player))return Result.reject("Open the locked cabinet first.");if(s.dialDigits[0]*100+s.dialDigits[1]*10+s.dialDigits[2]!=Integer.parseInt(Room2Config.cabinetCode()))return Result.reject("The lock does not open.");s.drawerOpen=true;return new Result(true,"","CabinetOpened");}
        case TAKE_KEYCARD->{if((s.roomNumber!=2&&s.roomNumber!=3)||!owns(s,"cabinet",player)||!s.drawerOpen)return Result.reject("Open the drawer first.");if(!s.keycardTaken){s.keycardTaken=true;if(!s.inventory.contains("Operator Keycard"))s.inventory.add("Operator Keycard");}return new Result(true,"","KeycardTaken");}
        case LOG_SUBMIT->{if((s.roomNumber!=2&&s.roomNumber!=3)||!owns(s,"log_archive",player))return Result.reject("Open the log archive first.");LogChecker.Result result=LogChecker.check(in.a,String.valueOf(in.i),Room2Config.attacker(),Room2Config.differentPorts());s.logSource=in.a==null?"":in.a.trim();s.differentPorts=in.i;s.logSolved=result.correct();if(!result.correctIp())return Result.reject("Wrong source IP.");if(!result.correctCount())return Result.reject("Wrong different-port count.");return new Result(true,"","AttackerIdentified");}
        case REGISTER_PAIR->{if((s.roomNumber!=2&&s.roomNumber!=3)||!owns(s,"service_register",player))return Result.reject("Open the service register first.");if(!Room2Config.servicePorts().containsKey(in.a)||!Room2Config.servicePorts().containsValue(in.b))return Result.reject("Unknown service or port.");for(Map.Entry<String,String> e:s.registerPairs.entrySet())if(!e.getKey().equals(in.a)&&e.getValue().equals(in.b))return Result.reject("That port is already paired.");s.registerPairs.put(in.a,in.b);return Result.ok();}
        case REGISTER_UNPAIR->{if((s.roomNumber!=2&&s.roomNumber!=3)||!owns(s,"service_register",player))return Result.reject("Open the service register first.");s.registerPairs.remove(in.a);return Result.ok();}
        case REGISTER_CHECK->{if((s.roomNumber!=2&&s.roomNumber!=3)||!owns(s,"service_register",player))return Result.reject("Open the service register first.");int correct=ServiceRegisterMatcher.countCorrect(s.registerPairs,Room2Config.servicePorts());if(ServiceRegisterMatcher.complete(s.registerPairs,Room2Config.servicePorts())){s.portsSolved=true;return new Result(true,"","RegisterVerified");}return Result.reject(correct+" of 6 are correct.");}
        case CCTV_FLAG->{if((s.roomNumber!=2&&s.roomNumber!=3)||!owns(s,"cctv_wall",player))return Result.reject("Open the camera wall first.");if(!CctvChecker.isValidCamera(in.i))return Result.reject("Select a camera from 1 to 9.");s.tamperedCamera=in.i;if(in.i==Room2Config.tamperedCamera()){s.cctvSolved=true;return new Result(true,"","TamperedCameraFound");}return Result.reject("CAM "+in.i+"'s clock matches the server. It is not tampered.");}
        case DOOR_CONFIRM->{if(s.roomNumber!=2&&s.roomNumber!=3)return Result.reject("Door confirmation is only used in Room 2.");if(player.equals(s.pausedBy)||player.isBlank())return Result.reject("Invalid player.");if("host".equalsIgnoreCase(in.a))s.doorConfirmHost=in.i!=0;else s.doorConfirmClient=in.i!=0;return Result.ok();}
        case PAUSE->{s.paused=true;s.pausedBy=player;return Result.ok();}case RESUME->{s.paused=false;s.pausedBy="";return Result.ok();}
        case USE_HINT->{if(s.hintsUsed>=21)return Result.reject("No hints remaining.");s.hintsUsed++;s.score=Math.max(0,s.score-50);s.secondsLeft=Math.max(0,s.secondsLeft-60);return Result.ok();}
        case UI_CLICK->{return Result.reject("Unsupported room action.");}
    }return Result.reject("Unsupported action.");}
    private static boolean sameLinks(List<int[]> actual,int[][] expected){if(actual.size()!=expected.length)return false;boolean[] used=new boolean[actual.size()];for(int[] e:expected){boolean found=false;for(int i=0;i<actual.size();i++){int[] a=actual.get(i);if(!used[i]&&((a[0]==e[0]&&a[1]==e[1])||(a[0]==e[1]&&a[1]==e[0]))){used[i]=true;found=true;break;}}if(!found)return false;}return true;}
    private static boolean owns(GameState s,String puzzle,String player){return Objects.equals(s.lockOwner.get(puzzle),player);}
    private Result terminal2(GameState s,String command,String player){if(!owns(s,"terminal2",player)&&!owns(s,"terminal3",player))return Result.reject("Open the control terminal first.");if(!s.keycardTaken)return Result.reject("Keycard required. Find the operator keycard.");String trimmed=command==null?"":command.trim();TerminalInterpreter2.Result r=TerminalInterpreter2.execute(trimmed,s.logSolved,s.attackerBlocked,s.cctvSolved,s.portsSolved,s.lockdownReleased);s.attackerBlocked=r.attackerBlocked();s.lockdownReleased=r.lockdownReleased();if(!trimmed.equalsIgnoreCase("clear")&&!trimmed.isBlank())s.terminalBuffer=(s.terminalBuffer+"\n> "+trimmed+"\n"+r.output()).trim();if(trimmed.equalsIgnoreCase("clear"))s.terminalBuffer="";if(r.output().contains("isolated"))return new Result(true,"","AttackerBlocked");if(r.lockdownReleased()&&!s.solved.contains("R2_RELEASE")&&!s.solved.contains("R3_RELEASE")){s.solved.add("R2_RELEASE");s.solved.add("R3_RELEASE");return new Result(true,"","LockdownReleased");}return r.output().startsWith("Cannot release")||r.output().startsWith("Invalid")||r.output().startsWith("No malicious")||r.output().startsWith("Evidence")?Result.reject(r.output()):Result.ok();}
    private Result terminal3(GameState s,String command,String player){return terminal2(s,command,player);}
    private static boolean portUsed(GameState s,int p){for(int[] l:s.links)if(l[0]==p||l[1]==p)return true;return false;}
}
